import photoIndex from "@/generated/photo-index.json";

/** Client-safe slice of the photo manifest, generated by scripts/scan-assets.mjs from src/data/photos.json. */
export interface IndexedPhoto {
  src: string;
  width: number;
  height: number;
  objectPosition?: string;
  blurDataURL?: string;
  credit: string;
  representative: boolean;
}

/** Approved photo for an image key (path). Usable from server and client components. */
export const indexedPhoto = (key: string): IndexedPhoto | undefined => (photoIndex as Record<string, IndexedPhoto>)[key];
